-- ============================================================================
-- ZestFlow Admin 种子数据
-- 职责：Admin 模块种子数据（租户、用户-租户关联、角色、演示场景）
-- 用法：在 init.sql 之后执行（或 Flyway 迁移时 include），使用对应数据库后再操作
-- 2026-06-02
-- ============================================================================

USE `zestflow_admin`;

-- ==================== 系统母版租户（tenant） ====================

VALUES (1, '系统母版', 'system-template', '模板租户，新租户从此拷贝初始数据', 1);

-- 2026-06-02：E2E 租户 B（多租户 / IP 演示隔离验收）
VALUES (2, 'E2E演示租户B', 'e2e-tenant-b', '企业级 E2E 多租户与 IP 映射验收专用', 1);

-- ==================== 用户-租户关联（user_tenant） ====================
-- 由 DefaultAdminInitializer 在 admin 首次启动时自动绑定租户 1、2（initData 执行时 user 尚不存在）

-- 2026-06-02：IP → 租户映射（需 zestflow.tenant.mode=multi 且 ip-demo-mode=enabled）
VALUES ('10.0.0.101', 2),
       ('10.0.0.102', 1);

-- ==================== 角色（role） — 母版租户默认三角色 ====================

VALUES ('APP_ADMIN', '应用管理员', '应用最高权限', 1, 'system'),
       ('APP_EDITOR', '应用编辑', '可编辑链路与配置', 1, 'system'),
       ('APP_VIEWER', '应用查看', '只读访问', 1, 'system');

